import { Group, Mesh, PlaneGeometry, MeshStandardNodeMaterial, DirectionalLight, Color, Vector3 } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();

  // --- Card backdrop ---
  const cardWidth = 2.5;
  const cardHeight = 2.0;
  const cardGeo = new PlaneGeometry(cardWidth, cardHeight);
  const cardMat = new MeshStandardNodeMaterial({
    color: new Color('#0b0b10'), // surface
    roughness: 0.6,
    metalness: 0.3,
    side: ctx.THREE.DoubleSide,
  });
  const card = new Mesh(cardGeo, cardMat);
  card.position.z = -0.05; // slightly behind gear
  group.add(card);

  // --- Caption strip (accent color) ---
  const stripHeight = 0.3;
  const stripGeo = new PlaneGeometry(cardWidth, stripHeight);
  const stripMat = new MeshStandardNodeMaterial({
    color: new Color('#ff2a38'), // accent
    roughness: 0.5,
    metalness: 0.2,
    side: ctx.THREE.DoubleSide,
  });
  const strip = new Mesh(stripGeo, stripMat);
  strip.position.set(0, -cardHeight/2 + stripHeight/2, -0.04);
  group.add(strip);

  // --- Load GLB gear mesh ---
  const gearGroup = new Group();
  group.add(gearGroup);

  ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
    const scene = gltf.scene;
    // Adjust scale/position if needed
    scene.scale.set(0.8, 0.8, 0.8);
    scene.position.z = 0.1; // slightly in front of card
    // Ensure PBR materials: set roughness/metalness to machined-metal
    scene.traverse((child) => {
      if (child.isMesh) {
        const mat = child.material;
        if (mat) {
          mat.roughness = 0.5;
          mat.metalness = 0.55;
          mat.clearcoat = 0.25;
          mat.needsUpdate = true;
        }
      }
    });
    gearGroup.add(scene);
  });

  // --- Accent rim light ---
  const rimLight = new DirectionalLight(new Color('#ff2a38'), 1.2);
  rimLight.position.set(2, 1, -3); // behind and to the right
  group.add(rimLight);

  // --- Weighted-settle entrance ---
  const entranceTimeline = gsap.timeline();
  entranceTimeline.fromTo(group.scale, { x: 0.96, y: 0.96, z: 0.96 }, {
    x: 1.04, y: 1.04, z: 1.04,
    duration: 0.7,
    ease: 'power3.out',
    onComplete: () => {
      gsap.to(group.scale, {
        x: 1, y: 1, z: 1,
        duration: 0.9,
        ease: 'power4.out',
      });
    }
  });

  // --- Hover interaction: rise-in subtle ---
  const hoverTimeline = gsap.timeline({ paused: true });
  hoverTimeline.to(group.position, {
    y: group.position.y + 0.15,
    duration: 0.3,
    ease: 'power2.out',
  });

  // --- Click interaction: emit event ---
  const clickHandler = () => {
    ctx.emit('hub-features.select', {});
  };

  // --- Cinematic primitives ---
  const primitivesCleanups = [];
  if (config.cinematicPrimitives) {
    for (const prim of config.cinematicPrimitives) {
      const result = ctx.primitives[prim.name](group, prim.params);
      if (result && result.cleanup) {
        primitivesCleanups.push(result.cleanup);
      }
    }
  }

  // --- Attach handlers ---
  group.userData.handlers = {
    pointerover: () => {
      hoverTimeline.play();
    },
    pointerout: () => {
      hoverTimeline.reverse();
    },
    click: clickHandler,
  };

  // --- Cleanup ---
  group.userData.cleanup = () => {
    entranceTimeline.kill();
    hoverTimeline.kill();
    cardGeo.dispose();
    cardMat.dispose();
    stripGeo.dispose();
    stripMat.dispose();
    // Dispose GLB resources (traverse gearGroup)
    gearGroup.traverse((child) => {
      if (child.isMesh) {
        child.geometry.dispose();
        if (child.material) {
          if (Array.isArray(child.material)) {
            child.material.forEach(m => m.dispose());
          } else {
            child.material.dispose();
          }
        }
      }
    });
    primitivesCleanups.forEach(fn => fn());
  };

  return group;
}
